{"code":"def transform(g):
 h,w=len(g),len(g[0])
 # block summarization; retain divider bands
 out=[r[:] for r in g]
 rs=[i for i in range(h) if all(x==5 for x in g[i])]; cs=[j for j in range(w) if all(g[i][j]==5 for i in range(h))]
 R=[-1]+rs+[h]; C=[-1]+cs+[w]
 for a in range(len(R)-1):
  for b in range(len(C)-1):
   x=[g[i][j] for i in range(R[a]+1,R[a+1]) for j in range(C[b]+1,C[b+1])]
   nz=[v for v in x if v not in (0,5)]
   v=0
   if nz:
    d={q:nz.count(q) for q in set(nz)}; v=max(d,key=lambda q:(d[q],-nz.index(q)))
   for i in range(R[a]+1,R[a+1]):
    for j in range(C[b]+1,C[b+1]): out[i][j]=v
 return out"}

